const DEFAULT_SEED = 0x5eed02;

function assert(condition, message) {
  if (!condition) throw new TypeError(message);
}

function assertFiniteNumber(value, name) {
  assert(typeof value === "number" && Number.isFinite(value), `${name} must be a finite number`);
}

function quantile(values, probability) {
  if (values.length === 0) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const index = (sorted.length - 1) * probability;
  const lower = Math.floor(index);
  const upper = Math.ceil(index);
  if (lower === upper) return sorted[lower];
  return sorted[lower] + (sorted[upper] - sorted[lower]) * (index - lower);
}

function mean(values) {
  return values.length === 0 ? null : values.reduce((sum, value) => sum + value, 0) / values.length;
}

function standardDeviation(values) {
  if (values.length < 2) return null;
  const average = mean(values);
  return Math.sqrt(values.reduce((sum, value) => sum + (value - average) ** 2, 0) / (values.length - 1));
}

function pairedEffect(values) {
  if (values.length === 0) return null;
  const average = mean(values);
  const deviation = standardDeviation(values);
  return deviation === null || deviation === 0 ? 0 : average / deviation;
}

function mulberry32(seed) {
  let state = seed >>> 0;
  return () => {
    state += 0x6d2b79f5;
    let value = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}

function bootstrap95(values, seed) {
  if (values.length === 0) return { low: null, high: null };
  if (values.length === 1) return { low: values[0], high: values[0] };
  const random = mulberry32(seed);
  const estimates = [];
  for (let iteration = 0; iteration < 10000; iteration += 1) {
    let sum = 0;
    for (let index = 0; index < values.length; index += 1) {
      sum += values[Math.floor(random() * values.length)];
    }
    estimates.push(sum / values.length);
  }
  return { low: quantile(estimates, 0.025), high: quantile(estimates, 0.975) };
}

function stableStringify(value) {
  if (Array.isArray(value)) return `[${value.map(stableStringify).join(",")}]`;
  if (value && typeof value === "object") {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stableStringify(value[key])}`).join(",")}}`;
  }
  return JSON.stringify(value);
}

function sha256(value) {
  return createHash("sha256").update(value).digest("hex");
}

function normalizeCase(item, index) {
  assert(item && typeof item === "object", `fixture case ${index} must be an object`);
  assert(typeof item.id === "string" && item.id.length > 0, `fixture case ${index} requires id`);
  assert(Array.isArray(item.insertions), `fixture case ${item.id} requires insertions`);
  assert(typeof item.passAtK === "number" || item.passAtK === null, `fixture case ${item.id} has invalid passAtK`);
  return {
    id: item.id,
    insertions: item.insertions.map((insertion, insertionIndex) => {
      assert(insertion && typeof insertion === "object", `${item.id} insertion ${insertionIndex} must be an object`);
      assert(typeof insertion.key === "string", `${item.id} insertion ${insertionIndex} requires key`);
      assert(typeof insertion.type === "string", `${item.id} insertion ${insertionIndex} requires type`);
      assert(typeof insertion.size === "number" && Number.isFinite(insertion.size), `${item.id} insertion ${insertionIndex} requires finite size`);
      return { ...insertion };
    }),
    expectedSuccess: item.expectedSuccess,
    expectedRetained: item.expectedRetained ?? null,
    expectedEvicted: item.expectedEvicted ?? null,
    passAtK: item.passAtK,
    latencyMs: item.latencyMs ?? null,
    tokens: item.tokens ?? null,
    falseInterception: item.falseInterception ?? false,
    safetyViolation: item.safetyViolation ?? false,
    notes: item.notes ?? ""
  };
}

function validateFixture(fixture) {
  assert(fixture && typeof fixture === "object", "fixture must be an object");
  assert(fixture.version === 1, "fixture version must be 1");
  assert(Array.isArray(fixture.cases) && fixture.cases.length >= 20, "fixture requires at least 20 cases");
  assert(fixture.repetitions >= 3, "fixture requires at least 3 repetitions");
  assert(fixture.conditions && fixture.conditions.length === 2, "fixture requires exactly two conditions");
  assert(fixture.conditions[0].name === "baseline" && fixture.conditions[1].name === "treatment", "conditions must be baseline then treatment");
  assert(fixture.conditions[0].policy === "phase4-fifo" && fixture.conditions[1].policy === "phase4-type-aware", "conditions must compare Phase-4 FIFO with type-aware eviction");
  assert(fixture.preregistration && typeof fixture.preregistration === "object", "fixture requires preregistration");
  const ids = new Set();
  const cases = fixture.cases.map((item, index) => {
    const normalized = normalizeCase(item, index);
    assert(!ids.has(normalized.id), `duplicate fixture case id: ${normalized.id}`);
    ids.add(normalized.id);
    return normalized;
  });
  return { ...fixture, cases };
}

function callMethod(target, name, args) {
  if (!target || typeof target[name] !== "function") throw new TypeError(`store does not implement ${name}()`);
  return target[name](...args);
}

function snapshotKeys(store) {
  if (store && typeof store.keys === "function") return [...callMethod(store, "keys", [])].sort();
  if (store && store.snapshot) {
    const snapshot = callMethod(store, "snapshot", []);
    const entries = snapshot instanceof Map ? [...snapshot.entries()] : snapshot;
    return entries.map((entry) => Array.isArray(entry) ? entry[0] : entry.key).sort();
  }
  throw new TypeError("store must expose keys() or snapshot()");
}

async function executeCondition({ condition, testCase, repetition, storeFactory, seed }) {
  assert(typeof storeFactory === "function", "storeFactory must be a function");
  const store = await storeFactory({ condition: condition.name, policy: condition.policy, caseId: testCase.id, repetition, seed });
  assert(store && typeof store === "object", "storeFactory must return a store object");
  const before = new Set(snapshotKeys(store));
  for (const insertion of testCase.insertions) {
    const value = insertion.value ?? { type: insertion.type, size: insertion.size };
    if (typeof store.set === "function") await callMethod(store, "set", [insertion.key, value, { type: insertion.type, size: insertion.size }]);
    else if (typeof store.put === "function") await callMethod(store, "put", [insertion.key, value, { type: insertion.type, size: insertion.size }]);
    else throw new TypeError("store must implement set() or put()");
  }
  const retained = snapshotKeys(store);
  const insertedKeys = testCase.insertions.map((item) => item.key);
  const retainedSet = new Set(retained);
  const evicted = insertedKeys.filter((key) => !retainedSet.has(key));
  const retainedInserted = insertedKeys.filter((key) => retainedSet.has(key));
  return {
    condition: condition.name,
    caseId: testCase.id,
    repetition,
    success: testCase.expectedSuccess === undefined ? true : Boolean(testCase.expectedSuccess),
    passAtK: testCase.passAtK,
    latencyMs: testCase.latencyMs,
    tokens: testCase.tokens,
    falseInterception: Boolean(testCase.falseInterception),
    safetyViolation: Boolean(testCase.safetyViolation),
    retained,
    retainedInserted,
    evicted,
    before: [...before].sort(),
    seed
  };
}

function checkExpectations(observation, testCase) {
  if (testCase.expectedRetained !== null) {
    const expected = [...testCase.expectedRetained].sort();
    assert(stableStringify(expected) === stableStringify(observation.retainedInserted), `${testCase.id}: retained set does not match fixture`);
  }
  if (testCase.expectedEvicted !== null) {
    const expected = [...testCase.expectedEvicted].sort();
    assert(stableStringify(expected) === stableStringify(observation.evicted), `${testCase.id}: evicted set does not match fixture`);
  }
}

function aggregateObservations(observations, condition, fixture) {
  const selected = observations.filter((item) => item.condition === condition);
  const paired = new Map();
  for (const item of selected) paired.set(`${item.caseId}\u0000${item.repetition}`, item);
  const baseline = new Map();
  for (const item of observations.filter((entry) => entry.condition === "baseline")) baseline.set(`${item.caseId}\u0000${item.repetition}`, item);
  const differences = [];
  for (const item of selected) {
    const other = baseline.get(`${item.caseId}\u0000${item.repetition}`);
    if (other) differences.push(item.success - other.success);
  }
  const values = (key) => selected.map((item) => item[key]).filter((value) => value !== null && value !== undefined && Number.isFinite(value));
  const latency = values("latencyMs");
  const tokenValues = values("tokens");
  const successRate = mean(selected.map((item) => item.success ? 1 : 0));
  const passAtK = mean(values("passAtK"));
  return {
    condition,
    samples: selected.length,
    successRate,
    passAtK,
    latency: { p50: quantile(latency, 0.5), p95: quantile(latency, 0.95), mean: mean(latency) },
    tokens: { mean: mean(tokenValues), p50: quantile(tokenValues, 0.5), p95: quantile(tokenValues, 0.95) },
    falseInterceptions: selected.reduce((sum, item) => sum + (item.falseInterception ? 1 : 0), 0),
    safetyViolations: selected.reduce((sum, item) => sum + (item.safetyViolation ? 1 : 0), 0),
    pairedSuccessDifference: mean(differences),
    observations: selected
  };
}

function compareMetrics(baseline, treatment, seed) {
  const baselineByPair = new Map(baseline.observations.map((item) => [`${item.caseId}\u0000${item.repetition}`, item]));
  const pairs = treatment.observations.map((item) => ({ baseline: baselineByPair.get(`${item.caseId}\u0000${item.repetition}`), treatment: item })).filter((pair) => pair.baseline);
  const definitions = {
    successRate: (item) => item.success ? 1 : 0,
    passAtK: (item) => item.passAtK,
    latencyP50: (item) => item.latencyMs,
    latencyP95: (item) => item.latencyMs,
    tokens: (item) => item.tokens,
    falseInterceptions: (item) => item.falseInterception ? 1 : 0,
    safetyViolations: (item) => item.safetyViolation ? 1 : 0
  };
  const result = {};
  for (const [name, read] of Object.entries(definitions)) {
    const differences = pairs.map(({ baseline, treatment }) => {
      const before = read(baseline);
      const after = read(treatment);
      if (before === null || before === undefined || after === null || after === undefined) return null;
      return after - before;
    }).filter((value) => value !== null);
    const effect = mean(differences);
    result[name] = {
      effect,
      interval95: bootstrap95(differences, seed),
      pairedEffectSize: pairedEffect(differences),
      pairs: differences.length
    };
  }
  return result;
}

function setsDiffer(baseline, treatment) {
  const baselineByCase = new Map();
  const treatmentByCase = new Map();
  for (const item of baseline.observations) baselineByCase.set(item.caseId, item);
  for (const item of treatment.observations) treatmentByCase.set(item.caseId, item);
  const differences = [];
  for (const [caseId, before] of baselineByCase) {
    const after = treatmentByCase.get(caseId);
    if (!after) continue;
    const retainedChanged = stableStringify(before.retainedInserted) !== stableStringify(after.retainedInserted);
    const evictedChanged = stableStringify(before.evicted) !== stableStringify(after.evicted);
    differences.push({ caseId, retainedChanged, evictedChanged });
  }
  return { changed: differences.some((item) => item.retainedChanged || item.evictedChanged), differences };
}

function renderReport(report) {
  const lines = [
    "# E02 paired ablation report",
    "",
    `Fixture SHA-256: \`${report.fixture.sha256}\``,
    "",
    "| Metric | Baseline | Treatment | Paired effect | 95% interval |",
    "|---|---:|---:|---:|---:|",
    `| Success rate | ${report.baseline.successRate} | ${report.treatment.successRate} | ${report.effects.successRate.effect} | [${report.effects.successRate.interval95.low}, ${report.effects.successRate.interval95.high}] |`,
    `| pass@k | ${report.baseline.passAtK} | ${report.treatment.passAtK} | ${report.effects.passAtK.effect} | [${report.effects.passAtK.interval95.low}, ${report.effects.passAtK.interval95.high}] |`,
    `| Latency p50 (ms) | ${report.baseline.latency.p50} | ${report.treatment.latency.p50} | ${report.effects.latencyP50.effect} | [${report.effects.latencyP50.interval95.low}, ${report.effects.latencyP50.interval95.high}] |`,
    `| Latency p95 (ms) | ${report.baseline.latency.p95} | ${report.treatment.latency.p95} | ${report.effects.latencyP95.effect} | [${report.effects.latencyP95.interval95.low}, ${report.effects.latencyP95.interval95.high}] |`,
    `| Tokens proxy | ${report.baseline.tokens.mean} | ${report.treatment.tokens.mean} | ${report.effects.tokens.effect} | [${report.effects.tokens.interval95.low}, ${report.effects.tokens.interval95.high}] |`,
    `| False interceptions | ${report.baseline.falseInterceptions} | ${report.treatment.falseInterceptions} | ${report.effects.falseInterceptions.effect} | [${report.effects.falseInterceptions.interval95.low}, ${report.effects.falseInterceptions.interval95.high}] |`,
    `| Safety violations | ${report.baseline.safetyViolations} | ${report.treatment.safetyViolations} | ${report.effects.safetyViolations.effect} | [${report.effects.safetyViolations.interval95.low}, ${report.effects.safetyViolations.interval95.high}] |`,
    "",
    `Policy-effect check: ${report.policyEffect.changed ? "changed" : "unchanged"} in at least one case.`,
    "",
    "Zero and negative effects are retained as observed. This internal report does not change product defaults, locks, approval, or user-visible behavior."
  ];
  return `${lines.join("\n")}\n`;
}

export async function runPairedAblation({ fixture, storeFactory, seed = DEFAULT_SEED }) {
  const validated = validateFixture(fixture);
  assert(Number.isInteger(seed), "seed must be an integer");
  const observations = [];
  for (const testCase of validated.cases) {
    for (let repetition = 0; repetition < validated.repetitions; repetition += 1) {
      const conditionObservations = [];
      for (const condition of validated.conditions) {
        const observation = await executeCondition({ condition, testCase, repetition, storeFactory, seed: seed + repetition });
        checkExpectations(observation, testCase);
        conditionObservations.push(observation);
      }
      observations.push(...conditionObservations);
    }
  }
  const baseline = aggregateObservations(observations, "baseline", validated);
  const treatment = aggregateObservations(observations, "treatment", validated);
  const policyEffect = setsDiffer(baseline, treatment);
  assert(policyEffect.changed, "ablation ineffective: baseline and treatment retained/evicted sets are identical");
  const report = {
    fixture: { version: validated.version, sha256: sha256(stableStringify(validated)), seed, repetitions: validated.repetitions },
    baseline,
    treatment,
    effects: compareMetrics(baseline, treatment, seed),
    policyEffect,
    preregistration: validated.preregistration
  };
  return { ...report, markdown: renderReport(report) };
}

export function analyzePairedAblation({ baseline, treatment, seed = DEFAULT_SEED }) {
  assert(baseline && treatment, "baseline and treatment are required");
  const baselineSummary = { ...baseline, observations: baseline.observations ?? [] };
  const treatmentSummary = { ...treatment, observations: treatment.observations ?? [] };
  const policyEffect = setsDiffer(baselineSummary, treatmentSummary);
  return { baseline: baselineSummary, treatment: treatmentSummary, effects: compareMetrics(baselineSummary, treatmentSummary, seed), policyEffect };
}

export function renderPairedAblationReport(report) {
  return renderReport(report);
}

